(()=>{const image=document.querySelector('.hero-art img');document.querySelectorAll('[data-landscape]').forEach(button=>{button.addEventListener('click',()=>{const landscape=button.dataset.landscape;image.src='assets/'+landscape;image.alt=landscape==='river.jpg'?'Agua fluyendo entre rocas y vegetación, paisaje natural de TERRA BEATS':'Bosque iluminado por la luz del sol, paisaje natural de TERRA BEATS';document.querySelectorAll('[data-landscape]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)))})})})();
